<?php $title='Dashboard';require 'includes/header.php';$pdo=db();$stats=[];$stats['interventions']=$pdo->query("SELECT COUNT(*) c FROM interventions")->fetch()['c'];$stats['active']=$pdo->query("SELECT COUNT(*) c FROM interventions WHERE status NOT IN ('terminee','annulee')")->fetch()['c'];$stats['sos']=$pdo->query("SELECT COUNT(*) c FROM sos_alerts WHERE status IN ('active','prise_en_charge')")->fetch()['c'];$stats['teams']=$pdo->query("SELECT COUNT(*) c FROM teams")->fetch()['c'];$sos=$pdo->query("SELECT s.*,t.nom team FROM sos_alerts s JOIN teams t ON t.id=s.team_id WHERE s.status IN ('active','prise_en_charge') ORDER BY s.created_at DESC LIMIT 10")->fetchAll();?>
<h1>Centre de contrôle</h1><div class="grid"><?php foreach([['Interventions',$stats['interventions']],['En cours',$stats['active']],['SOS actifs',$stats['sos']],['Équipes',$stats['teams']]] as $x):?><div class="card"><div><?=$x[0]?></div><div class="stat"><?=$x[1]?></div></div><?php endforeach;?></div><br><div class="toolbar"><h2>Alertes SOS actives</h2><a class="btn danger" href="sos/">Voir toutes</a></div><div class="table-wrap"><table class="table"><tr><th>Équipe</th><th>Position</th><th>Statut</th><th>Date</th></tr><?php foreach($sos as $s):?><tr><td><?=e($s['team'])?></td><td><?=e($s['latitude'])?>, <?=e($s['longitude'])?></td><td><span class="badge red"><?=e($s['status'])?></span></td><td><?=e($s['created_at'])?></td></tr><?php endforeach;?></table></div><div id="toast" class="toast"></div><?php require 'includes/footer.php';?>